import{_ as e,c as o,o as i,ag as l}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"疑難排解","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/troubleshooting.md","filePath":"zh-TW/guide/troubleshooting.md","lastUpdated":1791311600000}'),r={name:"zh-TW/guide/troubleshooting.md"};function t(d,a,n,h,c,s){return i(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="疑難排解" tabindex="-1">疑難排解 <a class="header-anchor" href="#疑難排解" aria-label="Permalink to &quot;疑難排解&quot;">​</a></h1><p>本頁彙整 nPlyr 在 macOS 與 iOS 上的常見問題及解決方法。</p><h2 id="應用程式無法啟動或啟動即崩潰" tabindex="-1">應用程式無法啟動或啟動即崩潰 <a class="header-anchor" href="#應用程式無法啟動或啟動即崩潰" aria-label="Permalink to &quot;應用程式無法啟動或啟動即崩潰&quot;">​</a></h2><ol><li>確認你的系統滿足最低要求（macOS 14 Sonoma 及以上，或 iOS / iPadOS 16 及以上）。</li><li>退出並重新啟動應用程式。</li><li>如果你側載了開發版本，請確認描述檔仍然有效。</li></ol><h2 id="影片無法播放-一直轉圈或報錯" tabindex="-1">影片無法播放（一直轉圈或報錯） <a class="header-anchor" href="#影片無法播放-一直轉圈或報錯" aria-label="Permalink to &quot;影片無法播放（一直轉圈或報錯）&quot;">​</a></h2><ul><li>確認連結是一個<strong>直鏈</strong>媒體 URL（<code>mp4</code>、<code>m3u8</code>、<code>flv</code>、<code>ts</code> 等），而不是一個頁面。使用<a href="/zh-TW/guide/browser.html">瀏覽器與嗅探器</a>擷取真正的連結。</li><li>某些網站需要特定的<strong>請求標頭</strong>（referer、cookie、auth）。透過嗅探器擷取連結會自動保留這些請求標頭。</li><li><code>TS → MP4</code> 透傳需要格式提示；如果某個 TS 來源失敗，請嘗試從線路切換器選擇另一條線路。</li><li>來自來源的 <code>403</code> 通常是短暫的網站側限流；請等待後重試，而不是盲目更改請求標頭。</li></ul><h2 id="嗅探器在某個網站上什麼也擷取不到" tabindex="-1">嗅探器在某個網站上什麼也擷取不到 <a class="header-anchor" href="#嗅探器在某個網站上什麼也擷取不到" aria-label="Permalink to &quot;嗅探器在某個網站上什麼也擷取不到&quot;">​</a></h2><ul><li>該頁面可能透過專有播放器或 DRM 載入影片，從不請求普通媒體檔案。此時，與該來源 API 通訊的<a href="/zh-TW/guide/miniapps.html">小程式</a>才是正確的工具。</li><li>嘗試重新載入頁面，或在<a href="/zh-TW/guide/settings.html">設定</a>中將<strong>瀏覽器 user-agent</strong>切換到行動裝置 / 桌面端。</li></ul><h2 id="某個鍵盤快捷鍵不起作用" tabindex="-1">某個鍵盤快捷鍵不起作用 <a class="header-anchor" href="#某個鍵盤快捷鍵不起作用" aria-label="Permalink to &quot;某個鍵盤快捷鍵不起作用&quot;">​</a></h2><ul><li>快捷鍵僅按修飾鍵匹配（<code>⌘</code>、<code>⌥</code>、<code>⌃</code>、<code>⇧</code>）；方向鍵與小鍵盤不屬於綁定的一部分。</li><li>當你在文字框（URL 列、搜尋框）中輸入時，單鍵快捷鍵會被有意抑制，以免與你的輸入衝突。</li><li>如果某個綁定依然感覺失效，請檢查它是否在<strong>系統設定 → 鍵盤 → 鍵盤快捷鍵</strong>中被系統或應用程式快捷鍵遮蔽。</li></ul><h2 id="下載停滯或失敗" tabindex="-1">下載停滯或失敗 <a class="header-anchor" href="#下載停滯或失敗" aria-label="Permalink to &quot;下載停滯或失敗&quot;">​</a></h2><ul><li>單一片段失敗會將下載標記為 <code>.failed</code>；可從標記檔案續傳。</li><li>如果某個網域反覆回傳 <code>404</code>，nPlyr 會在本次工作階段中將其列入黑名單，且不會靜默改道——請選擇另一個來源。</li><li>重新封裝失敗會保留原始 <code>.ts</code> 並標記為 <code>completed</code>，因此你的資料不會遺失。</li></ul><h2 id="某個小程式的行為與-android-上不同" tabindex="-1">某個小程式的行為與 Android 上不同 <a class="header-anchor" href="#某個小程式的行為與-android-上不同" aria-label="Permalink to &quot;某個小程式的行為與 Android 上不同&quot;">​</a></h2><p>原始引擎是 Android/Java（Rhino）。nPlyr 在 JavaScriptCore 上執行規則，並為規則所依賴的部分實作了一個 <strong>Rhino→Java 相容層</strong>。部分 Java 特有的行為是有意不支援的。請查閱<a href="/zh-TW/guide/miniapp-compatibility.html">相容性</a>頁面；如果某條具體規則失敗，請回報規則名稱。</p><h2 id="重置-nplyr" tabindex="-1">重置 nPlyr <a class="header-anchor" href="#重置-nplyr" aria-label="Permalink to &quot;重置 nPlyr&quot;">​</a></h2><p>你可以從<strong>設定 → 進階 → 重設</strong>重置應用程式的本機資料（媒體庫、書籤、小程式變數）。這不會影響你已購買的解鎖。</p>',16)])])}const p=e(r,[["render",t]]);export{m as __pageData,p as default};
